    {
      "claim_id": "parser_leaked_on_parse_error",
      "necessary": "yes",
      "necessity_reason": "A finite input such as an unmatched opening brace produces a parser error after allocation. The harness returns when it sees that error without freeing the parser, leaving its allocated state alive.",
      "before": {
        "requirement": "Release the parser and its owned state when string parsing reports an error.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The parser cleanup operation existed, but the harness returns from the error branch before calling it.",
